  "loc.src.data.hazardlanguage.field.hint.009d3125a86d": "Nebula: sensors wash out and ambushers hide in the murk — route around it, or cross eyes-open.",
  "loc.src.data.hazardlanguage.field.hint.2dd9e8ab344b": "Dense rock: collisions chew hull — thread the gaps slowly, time the tumbles, or tether-swing through.",
  "loc.src.data.hazardlanguage.field.hint.3c718be5d37b": "Nebula fog: your scanner goes blind before you do — route around, or watch for shapes in the murk.",
  "loc.src.data.hazardlanguage.field.hint.450408cfcec4": "Radiation field ahead: shields and cargo cook inside — shield up, cross fast, or route around.",
  "loc.src.data.hazardlanguage.field.hint.4c9a5fd2abe2": "Debris field: fast junk on flat arcs — keep your speed down and time the crossings.",
  "loc.src.data.hazardlanguage.field.hint.78e264bfb195": "Radiation: it burns shields and cargo the whole time you are inside — shield up, transit fast, or route around.",
  "loc.src.data.hazardlanguage.field.hint.c507db0808c8": "Debris current: the warning rails precede each surge — time the calm, tether the ballast, or route around.",
  "loc.src.data.hazardlanguage.field.name.64fc4343c626": "hazardHints",
