  "loc.src.data.missionconditions.field.brief.5d108a3b39a5": "Break one core chunk loose.",
  "loc.src.data.missionconditions.field.brief.71b0eca3e761": "Arrive under {BERTH_SPEED} wu/s.",
  "loc.src.data.missionconditions.field.brief.7ba5fd0019f4": "Do not let the line go slack.",
  "loc.src.data.missionconditions.field.brief.9620b5c19d1c": "Land one clean Massline release.",
  "loc.src.data.missionconditions.field.brief.b89c426a12d7": "Do not crack the freight.",
  "loc.src.data.missionconditions.field.brief.c64341244670": "Land three vent bonuses.",
  "loc.src.data.missionconditions.field.brief.ccca450cdb0b": "Approach the drop cold.",
  "loc.src.data.missionconditions.field.label.3a68d9a9297c": "One clean release",
