  "loc.src.data.missionconditions.field.label.c346f6a8f8a3": "Steady hands",
  "loc.src.data.missionconditions.field.label.ca40f8f23abe": "Fragile — intact",
  "loc.src.data.missionconditions.field.label.ceda4230d8da": "Weapons cold",
  "loc.src.data.missionconditions.field.label.de77af8289c7": "Throw it",
  "loc.src.data.missionconditions.field.label.e4cf38f7c4d3": "Three clean vents",
  "loc.src.data.missionconditions.field.label.e96754b59f7a": "Put mass on them",
  "loc.src.data.missionconditions.field.prose.4b70a5d63889": "Fill this quota without pegging the beam once. Pulse it.",
  "loc.src.data.missionconditions.field.prose.4b808dfb5a60": "Land one solid mass strike on this job — a rock, a wreck, anything with weight behind it.",
  "loc.src.data.missionconditions.field.prose.4de3c1384026": "This freight does not survive a hard knock. Crack any of it and the contract is void.",
  "loc.src.data.missionconditions.field.prose.820c953dc6d1": "Come into the destination quiet — no sustained burn above {QUIET_APPROACH_SPEED} wu/s inside {QUIET_APPROACH_RANGE_WU} wu of it.",
  "loc.src.data.missionconditions.field.prose.82ce80487176": "Crack something big enough to leave a core chunk behind. That is what the refinery is short of.",
  "loc.src.data.missionconditions.field.prose.8688a5e50a5c": "Once you are on the load, keep the line working. Three seconds of slack forfeits the recovery premium.",
  "loc.src.data.missionconditions.field.prose.96472da14c84": "The buyer is paying for technique: land three vent bonuses while you fill this.",
  "loc.src.data.missionconditions.field.prose.9a8975cb9458": "Show them the line works: one clean or razor release logged before you file this.",
  "loc.src.data.missionconditions.field.prose.be487eab6a7e": "Never exceed {STEADY_SPEED_LIMIT} wu/s while the manifest is aboard. The premium is paid on a calm run.",
  "loc.src.data.missionconditions.field.prose.e4b15f7ef967": "Match the berth before you hand over: inside {BERTH_RANGE_WU} wu of the destination and under {BERTH_SPEED} wu/s.",
  "loc.src.data.missionconditions.field.prose.f27065723256": "Finish at least one of them with a thrown mass, not a gun.",
  "loc.src.data.missionconditions.field.prose.f49396350019": "Run this one without firing. Shove, tow and outfly — but do not shoot.",
