  "loc.src.systems.buildidentity.field.summary.07c92a1a3bb5": "Impact hardware and charge capacity favor burst collisions.",
  "loc.src.systems.buildidentity.field.summary.09595140877f": "Extraction hull; drill and cargo decisions define the threat.",
  "loc.src.systems.buildidentity.field.summary.2de77b2113f2": "Flexible hull; scan the modules before assuming its job.",
  "loc.src.systems.buildidentity.field.summary.3a25d18626f8": "Cargo-first hull; expect poor turning and a loaded hold.",
  "loc.src.systems.buildidentity.field.summary.3e4e4283f2eb": "Combat hull with heavier arcs and sustained pressure.",
  "loc.src.systems.buildidentity.field.summary.445bfeef161c": "Mining gear defines the build; watch the drill line.",
  "loc.src.systems.buildidentity.field.summary.4d822c1a1795": "No strong module pair detected; use the hull role as the read.",
  "loc.src.systems.buildidentity.field.summary.4dacba415958": "Extraction plus hold space points to long-haul mining.",
  "loc.src.systems.buildidentity.field.summary.719c938031eb": "Baseline utility hull; read the fittings for its specialty.",
  "loc.src.systems.buildidentity.field.summary.7b11efe83dd2": "Fast combat hull built around burst positioning.",
  "loc.src.systems.buildidentity.field.summary.894ffd53c688": "Cargo hull with hidden space; customs risk matters.",
  "loc.src.systems.buildidentity.field.summary.a06fd665d9f8": "Sensor-forward hull that prefers information and range.",
  "loc.src.systems.buildidentity.field.summary.a69e84a7bdaf": "Heavy combat hull; treat its mass as part of the weapon.",
  "loc.src.systems.buildidentity.field.summary.b459ce6711dc": "Winch authority plus charges can reposition fights.",
  "loc.src.systems.buildidentity.field.summary.b9519c267070": "Light combat hull with direct-fire pressure.",
  "loc.src.systems.buildidentity.field.summary.cf3c0e1af2fa": "Sensor gear makes information the build advantage.",
  "loc.src.systems.buildidentity.field.summary.f5567df97c98": "Cargo mass plus ram hardware turns the hold into impact threat.",
