  "loc.src.ui.screens.missionlog.dom.textcontent.c22eb92690cf": "CAMPAIGN THREAD",
  "loc.src.ui.screens.missionlog.field.body.0757dea85f8b": "Plot or review the jump route to this trade destination.",
  "loc.src.ui.screens.missionlog.field.body.0c0961486db0": "Complete your faction chain and keep the next contract tracked between docks.",
  "loc.src.ui.screens.missionlog.field.body.0c187b06bbd0": "Career contracts, claims, trade, mining, combat, and exploration continue after 47-A.",
  "loc.src.ui.screens.missionlog.field.body.1c0c4dd268fe": "{descriptor_stage_instruction} {stateLabel}: dock at {station_station_name_stationId} and open Missions.",
  "loc.src.ui.screens.missionlog.field.body.348f978ee16b": "Mine the 47-A signal, then dock at Helios before the manifest rolls over.",
  "loc.src.ui.screens.missionlog.field.body.37f40be98456": "Pick a nearby R0-R1 contract first; reliable payouts beat distant prestige early.",
  "loc.src.ui.screens.missionlog.field.body.455d1ab9431d": "Open the galaxy chart and compare the two authored continuation routes.",
  "loc.src.ui.screens.missionlog.field.body.473725d830bb": "Accept an intro contract from MTS, SCN, or the Free Captains to lock your first path.",
  "loc.src.ui.screens.missionlog.field.body.4cec05bad2aa": "Show the trade destination marker and nearby station contacts.",
  "loc.src.ui.screens.missionlog.field.body.4e87c7620979": "{house}: {routeBody}",
  "loc.src.ui.screens.missionlog.field.body.56e41f76010c": "Pick a low-risk cargo or trade contract from a station board, then track it before undocking.",
  "loc.src.ui.screens.missionlog.field.body.7a1d60f4ee9c": "Fit the Hitch for a low-risk bounty, track the target, and cash the first kill.",
  "loc.src.ui.screens.missionlog.field.body.8f0d6fc76fd9": "Deploy a drone, trader, or outpost so the sector starts earning while you fly.",
  "loc.src.ui.screens.missionlog.field.body.948fd25c39c6": "Plot or review the jump route to this objective.",
  "loc.src.ui.screens.missionlog.field.body.97216ed4d567": "Set one active contract as your nav target before leaving the station lane.",
  "loc.src.ui.screens.missionlog.field.body.9c41918ee687": "Plot a normal destination, then start the departure to reach the stay-or-leave preflight.",
  "loc.src.ui.screens.missionlog.field.body.abd38f5d8945": "Continue career contracts, claims, trade, mining, combat, and exploration while the next route settles.",
  "loc.src.ui.screens.missionlog.field.body.bf837fe738c8": "Reach 100,000cr net worth and 50 branch standing. Own a capital hull, claim, or outpost to qualify for a filed ending.",
  "loc.src.ui.screens.missionlog.field.body.c07667170bcd": "The hold is nearly full. Sell goods or finish a delivery before taking another one-load contract.",
  "loc.src.ui.screens.missionlog.field.body.c91c4f9ee2b1": "Early mining and haul jobs pay fastest when you leave enough room for contract cargo.",
  "loc.src.ui.screens.missionlog.field.body.d8865cb4fe70": "Run short hauls, mining, or safe bounty work until a tier-2 hull is affordable.",
  "loc.src.ui.screens.missionlog.field.body.e38e6dc41fce": "Show the live objective marker and nearby contacts.",
  "loc.src.ui.screens.missionlog.field.body.f2502a1ceab9": "{chain_choicePrompt} {options_join}. Dock at either board to commit.",
  "loc.src.ui.screens.missionlog.field.body.f592590f3d76": "Close {title}? Other professional paths stay open.",
