  "loc.src.ui.screens.outfitting.field.text.0966f465dc56": "Utility and engine upgrades shorten the sweep; shields cover mistakes in dirty lanes.",
  "loc.src.ui.screens.outfitting.field.text.331127fca55c": "Mining beams and cargo racks shorten the loop; shields keep the ore run from turning into debris.",
  "loc.src.ui.screens.outfitting.field.text.619fc577ce16": "Bring cargo space for the claim and enough shield or utility support to survive the wreck field.",
  "loc.src.ui.screens.outfitting.field.text.66f78e9f30d9": "Unfit {conflict_name} before fitting another head",
  "loc.src.ui.screens.outfitting.field.text.847e8be20b64": "Weapons make the timer honest; shields and engines decide whether you leave with the bounty or become it.",
  "loc.src.ui.screens.outfitting.field.text.872d798ac7fe": "Use the tracked contract to buy toward a job instead of buying anonymous numbers in a vacuum.",
  "loc.src.ui.screens.outfitting.field.text.c0916abd3da6": "Sustained weapons and shields matter more than cargo; fit to stay alive beside the convoy.",
  "loc.src.ui.screens.outfitting.field.text.d6b582ece4c1": "Engine and shield upgrades protect the schedule; cargo is secondary unless the job also asks for freight.",
  "loc.src.ui.screens.outfitting.field.text.e55b52316a73": "Speed and cargo beat fair fights here; shields are the apology letter if a patrol gets curious.",
  "loc.src.ui.screens.outfitting.field.text.f8c5e9d20c4b": "Cargo space is the payout lever; add engine or shield margin only after the hold can carry the contract cleanly.",
  "loc.src.ui.screens.outfitting.field.title.01fe88cb446d": "Need compatible hull slot: {pick_def_name}",
  "loc.src.ui.screens.outfitting.field.title.15b7b86bd7c6": "Buy {def_name} and fit it to the {slot_type_def_slotType} {slot_size_def_size} slot.",
